INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'adversity', 'n.', '/ədˈvɜːsəti/', '困境;逆境', 'Great courage is often shown in times of adversity.', '巨大的勇气往往在逆境之中显现。', 'Adversity and Courage', 1, 0, 'senior', 'wordlist', 'elective3', 'U4', 'in adversity', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'expedition', 'n.', '/ˌekspəˈdɪʃn/', '探险;远征;探险队', 'Shackleton led a famous expedition to the Antarctic.', '沙克尔顿率领了一支著名的南极探险队。', 'Adversity and Courage', 2, 0, 'senior', 'wordlist', 'elective3', 'U4', 'an Antarctic expedition', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'voyage', 'n.', '/ˈvɔɪɪdʒ/', '航海;航行;旅程', 'Their voyage across the icy sea was dangerous and difficult.', '他们穿越冰海的航行既危险又艰难。', 'Adversity and Courage', 3, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a long voyage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'crew', 'n.', '/kruː/', '全体船员;全体工作人员;一群人', 'The whole crew had to camp on the ice after the ship sank.', '船沉没后,全体船员只得在冰面上扎营。', 'Adversity and Courage', 4, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the crew of the ship', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'abandon', 'v.', '/əˈbændən/', '舍弃;抛弃;放弃', 'The captain gave the order to abandon ship before it was crushed.', '船被压碎前,船长下令弃船。', 'Adversity and Courage', 5, 0, 'senior', 'wordlist', 'elective3', 'U4', 'abandon ship', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'aboard', 'adv./prep.', '/əˈbɔːd/', '在(船、飞机、车)上;上(船、飞机、车)', 'With a friend''s help, the boy managed to get aboard the ship.', '在朋友的帮助下,这个男孩设法登上了船。', 'Adversity and Courage', 6, 0, 'senior', 'wordlist', 'elective3', 'U4', 'get aboard', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sink', 'v.', '/sɪŋk/', '沉没;下沉;下降;使下沉', 'The crew watched their ship slowly sink into the freezing sea.', '船员们眼看着自己的船慢慢沉入冰冷的海里。', 'Adversity and Courage', 7, 0, 'senior', 'wordlist', 'elective3', 'U4', 'sink into the sea', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'crush', 'v.', '/krʌʃ/', '压碎;压坏;毁坏', 'The ship was crushed by the thick ice and could no longer sail.', '船被厚厚的冰压碎,再也无法航行了。', 'Adversity and Courage', 8, 0, 'senior', 'wordlist', 'elective3', 'U4', 'be crushed by the ice', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rough', 'adj.', '/rʌf/', '汹涌的;粗糙的;粗略的', 'They sailed for days on rough seas before reaching the island.', '他们在汹涌的海上航行了好几天才到达那座岛。', 'Adversity and Courage', 9, 0, 'senior', 'wordlist', 'elective3', 'U4', 'rough seas', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'navigator', 'n.', '/ˈnævɪɡeɪtə(r)/', '领航员;航行者', 'A skilled navigator was needed to guide the small boat safely.', '需要一位熟练的领航员引导小船安全前行。', 'Adversity and Courage', 10, 0, 'senior', 'wordlist', 'elective3', 'U4', 'an excellent navigator', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'navy', 'n.', '/ˈneɪvi/', '海军;海军部队', 'No navy in the world ever stopped at that lonely island.', '世界上没有哪支海军曾在那座孤岛停靠。', 'Adversity and Courage', 11, 0, 'senior', 'wordlist', 'elective3', 'U4', 'join the navy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'perseverance', 'n.', '/ˌpɜːsɪˈvɪərəns/', '毅力;韧性;不屈不挠的精神', 'Only through perseverance did the men survive four months on the ice.', '正是凭着毅力,这些人才在冰上存活了四个月。', 'Adversity and Courage', 12, 0, 'senior', 'wordlist', 'elective3', 'U4', 'with perseverance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'persevere', 'v.', '/ˌpɜːsɪˈvɪə(r)/', '坚持;孜孜以求', 'They chose to persevere even when all hope seemed lost.', '即使似乎已毫无希望,他们仍选择坚持下去。', 'Adversity and Courage', 13, 0, 'senior', 'wordlist', 'elective3', 'U4', 'persevere in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'endurance', 'n.', '/ɪnˈdjʊərəns/', '忍耐力;耐久力', 'Surviving the cold called for both courage and endurance.', '熬过严寒既需要勇气,也需要忍耐力。', 'Adversity and Courage', 14, 0, 'senior', 'wordlist', 'elective3', 'U4', 'great endurance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'resolve', 'v./n.', '/rɪˈzɒlv/', '决心;下定决心;解决(问题);坚定的信念', 'Their firm resolve to get home filled the men with hope.', '他们回家的坚定决心让大家充满希望。', 'Adversity and Courage', 15, 0, 'senior', 'wordlist', 'elective3', 'U4', 'firm resolve', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'resolution', 'n.', '/ˌrezəˈluːʃn/', '决心;决议;解决', 'He made a resolution to finish what he had started.', '他下定决心要完成自己开始的事。', 'Adversity and Courage', 16, 0, 'senior', 'wordlist', 'elective3', 'U4', 'make a resolution', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'commitment', 'n.', '/kəˈmɪtmənt/', '承诺;奉献;投入', 'The leader''s commitment to his men saved them from death.', '这位领队对部下的奉献把他们从死亡中拯救出来。', 'Adversity and Courage', 17, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a strong commitment', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'loyal', 'adj.', '/ˈlɔɪəl/', '忠诚的;忠实的', 'Frank Wild stayed loyal to Shackleton through every hardship.', '弗兰克·怀尔德在每一次艰难中都对沙克尔顿忠心耿耿。', 'Adversity and Courage', 18, 0, 'senior', 'wordlist', 'elective3', 'U4', 'loyal to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'genuine', 'adj.', '/ˈdʒenjuɪn/', '真正的;真诚的;可信赖的', 'Their genuine concern for others kept the whole group together.', '他们对他人真诚的关心让整个团队团结在一起。', 'Adversity and Courage', 19, 0, 'senior', 'wordlist', 'elective3', 'U4', 'genuine concern', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'selfish', 'adj.', '/ˈselfɪʃ/', '自私的', 'In such danger, no one could afford to be selfish.', '在这样的危险中,没有人能够自私自利。', 'Adversity and Courage', 20, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a selfish man', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'miserable', 'adj.', '/ˈmɪzrəbl/', '痛苦的;悲惨的;令人难受的', 'They were crowded together in that cold and miserable place.', '他们挤在那个又冷又凄惨的地方。', 'Adversity and Courage', 21, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a miserable place', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cruel', 'adj.', '/ˈkruːəl/', '残酷的;残忍的;冷酷的', 'The cruel weather of the Antarctic tested their courage every day.', '南极残酷的天气每天都在考验着他们的勇气。', 'Adversity and Courage', 22, 0, 'senior', 'wordlist', 'elective3', 'U4', 'cruel weather', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'damp', 'adj.', '/dæmp/', '潮湿的;湿气重的', 'Their damp clothes made the freezing nights even harder to bear.', '潮湿的衣服让冰冷的夜晚更加难熬。', 'Adversity and Courage', 23, 0, 'senior', 'wordlist', 'elective3', 'U4', 'damp clothes', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'decent', 'adj.', '/ˈdiːsnt/', '相当不错的;正派的;得体的', 'He dreamed of decent food and a warm, dry bedroom.', '他梦想着像样的食物和一间温暖干燥的卧室。', 'Adversity and Courage', 24, 0, 'senior', 'wordlist', 'elective3', 'U4', 'decent food', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cosy', 'adj.', '/ˈkəʊzi/', '温馨的;舒适的', 'He tried to picture a cosy bedroom far from the icy shore.', '他努力想象一间远离冰岸的温馨卧室。', 'Adversity and Courage', 25, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a cosy bedroom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'episode', 'n.', '/ˈepɪsəʊd/', '(人生的)一段经历;(故事的)片段;插曲', 'This was an episode in his life that he would never forget.', '这是他一生中永远难忘的一段经历。', 'Adversity and Courage', 26, 0, 'senior', 'wordlist', 'elective3', 'U4', 'an episode in one''s life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'motive', 'n.', '/ˈməʊtɪv/', '动机;原因;目的', 'For many, the motive for joining was to experience a great adventure.', '对许多人来说,参加的动机是去体验一场伟大的冒险。', 'Adversity and Courage', 27, 0, 'senior', 'wordlist', 'elective3', 'U4', 'the motive for', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'envy', 'v./n.', '/ˈenvi/', '羡慕;妒忌', 'Back home, friends would envy him for his amazing adventure.', '回到家后,朋友们会羡慕他经历了这场奇妙的冒险。', 'Adversity and Courage', 28, 0, 'senior', 'wordlist', 'elective3', 'U4', 'envy somebody', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'qualified', 'adj.', '/ˈkwɒlɪfaɪd/', '合格的;有资格的;胜任的', 'At first he was not qualified enough to join the expedition.', '起初他还不够资格加入这次探险。', 'Adversity and Courage', 29, 0, 'senior', 'wordlist', 'elective3', 'U4', 'qualified enough', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'assign', 'v.', '/əˈsaɪn/', '分派;布置;分配', 'The captain assigned the boy the job of cooking for the crew.', '船长把为船员做饭的工作分派给了这个男孩。', 'Adversity and Courage', 30, 0, 'senior', 'wordlist', 'elective3', 'U4', 'assign somebody a job', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'thorough', 'adj.', '/ˈθʌrə/', '深入的;彻底的;细致的', 'The officer carried out a thorough search of the wrecked ship.', '那名军官对失事的船进行了彻底的搜查。', 'Adversity and Courage', 31, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a thorough investigation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'vigour', 'n.', '/ˈvɪɡə(r)/', '精力;力量;活力', 'Despite the cold, the men worked with surprising vigour.', '尽管天寒,这些人仍以惊人的活力工作着。', 'Adversity and Courage', 32, 0, 'senior', 'wordlist', 'elective3', 'U4', 'with great vigour', '美式拼 vigor;美音 /ˈvɪɡər/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'enthusiastic', 'adj.', '/ɪnˌθjuːziˈæstɪk/', '热情的;热心的', 'He was so enthusiastic about adventure that he hid aboard the ship.', '他对冒险如此热衷,以至于偷偷藏在了船上。', 'Adversity and Courage', 33, 0, 'senior', 'wordlist', 'elective3', 'U4', 'enthusiastic about', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fortunately', 'adv.', '/ˈfɔːtʃənətli/', '幸运地', 'Fortunately, every member of the crew was finally rescued.', '幸运的是,全体船员最终都获救了。', 'Adversity and Courage', 34, 0, 'senior', 'wordlist', 'elective3', 'U4', 'fortunately for them', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'unfortunately', 'adv.', '/ʌnˈfɔːtʃənətli/', '不幸地;遗憾地', 'Unfortunately, his first application to join was turned down.', '遗憾的是,他第一次加入的申请被拒绝了。', 'Adversity and Courage', 35, 0, 'senior', 'wordlist', 'elective3', 'U4', 'unfortunately for him', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'guidance', 'n.', '/ˈɡaɪdns/', '指导;引导;导航', 'Under their leader''s guidance, the men never lost hope.', '在领队的指引下,这些人从未失去希望。', 'Adversity and Courage', 36, 0, 'senior', 'wordlist', 'elective3', 'U4', 'under one''s guidance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'recreation', 'n.', '/ˌrekriˈeɪʃn/', '娱乐;消遣', 'On the island, music was their only form of recreation.', '在岛上,音乐是他们唯一的消遣方式。', 'Adversity and Courage', 37, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a form of recreation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'bark', 'v./n.', '/bɑːk/', '(狗)吠叫;吠叫声', 'The sled dogs would bark loudly whenever danger came near.', '每当危险临近,雪橇犬就会大声吠叫。', 'Adversity and Courage', 38, 0, 'senior', 'wordlist', 'elective3', 'U4', 'bark loudly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'wage', 'n.', '/weɪdʒ/', '工资;工钱', 'Explorers were paid low wages for such dangerous voyages.', '探险者们做这种危险的航行只能拿到很低的工钱。', 'Adversity and Courage', 39, 0, 'senior', 'wordlist', 'elective3', 'U4', 'low wages', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'corporate', 'adj.', '/ˈkɔːpərət/', '公司的;法人的;团体的', 'The company launched a campaign to promote its corporate image.', '公司发起了一项活动来提升其企业形象。', 'Adversity and Courage', 40, 0, 'senior', 'wordlist', 'elective3', 'U4', 'corporate image', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'advertise', 'v.', '/ˈædvətaɪz/', '公布;宣传;做广告', 'The leader had advertised for brave men to join the expedition.', '领队曾登广告招募勇敢的人加入探险。', 'Adversity and Courage', 41, 0, 'senior', 'wordlist', 'elective3', 'U4', 'advertise for', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'advertising', 'n.', '/ˈædvətaɪzɪŋ/', '广告活动;广告业', 'An advertising campaign helped attract more volunteers.', '一场广告宣传帮助吸引了更多志愿者。', 'Adversity and Courage', 42, 0, 'senior', 'wordlist', 'elective3', 'U4', 'an advertising campaign', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'motor', 'n.', '/ˈməʊtə(r)/', '发动机;马达', 'One crew member was a motor expert who could fix the engine.', '有一名船员是能修引擎的马达专家。', 'Adversity and Courage', 43, 0, 'senior', 'wordlist', 'elective3', 'U4', 'a motor expert', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'nephew', 'n.', '/ˈnefjuː/', '侄子;外甥', 'My young nephew loves reading stories of brave explorers.', '我年幼的外甥喜欢读勇敢探险者的故事。', 'Adversity and Courage', 44, 0, 'senior', 'wordlist', 'elective3', 'U4', 'my young nephew', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'furniture', 'n.', '/ˈfɜːnɪtʃə(r)/', '家具', 'It took great effort to move all the heavy furniture inside.', '把所有沉重的家具搬进来费了很大力气。', 'Adversity and Courage', 45, 0, 'senior', 'wordlist', 'elective3', 'U4', 'move the furniture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cupboard', 'n.', '/ˈkʌbəd/', '橱柜;壁橱', 'The young boy hid in a cupboard until the ship had set off.', '船出发后,小男孩一直藏在橱柜里。', 'Adversity and Courage', 46, 0, 'senior', 'wordlist', 'elective3', 'U4', 'hide in a cupboard', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'stove', 'n.', '/stəʊv/', '炉子;灶具', 'They gathered by the small stove to keep themselves warm.', '他们围在小炉子旁取暖。', 'Adversity and Courage', 47, 0, 'senior', 'wordlist', 'elective3', 'U4', 'by the stove', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rugby', 'n.', '/ˈrʌɡbi/', '橄榄球运动', 'He had been playing rugby since the age of eight.', '他从八岁起就一直在打橄榄球。', 'Adversity and Courage', 48, 0, 'senior', 'wordlist', 'elective3', 'U4', 'play rugby', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u4.01', '①表从过去持续到现在的动作(for/since/all day/how long)', 'A2', 12, '选择性必修三 U4 — 动作从过去某时一直延续到现在并可能继续,常与 for + 一段时间、since + 起点、all day、how long 连用 → 用 have/has been doing。', 1, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u4.02', '②强调动作的反复/持续,或刚结束留下明显结果', 'A2', 12, '选择性必修三 U4 — 强调动作一直在反复进行,或动作刚停下但留下可见结果(累了/湿了/脏了)→ 用 have/has been doing 突出''一直在做''。', 2, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u4.03', '③与现在完成时(have done)、现在进行时(am doing)对照', 'A2', 12, '选择性必修三 U4 — 强调''一直在做、还没必然完成''用 have/has been doing;强调''已完成/结果''用 have done;只说此刻在做用 am/is/are doing。看语境标志选择。', 3, 'elective3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'I ____ for this climb for months, and I finally feel ready.', 'have been training', 'have trained', 'am training', 'had been training', 'A', 'for months 表一段时间、动作持续到现在并可能继续 → have been training。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'She ____ in her diary since the expedition first set off.', 'has written', 'has been writing', 'is writing', 'wrote', 'B', 'since + 起点、动作从那时持续至今 → has been writing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'The crew ____ on rough seas for days before they reached the island.', 'has sailed', 'is sailing', 'have been sailing', 'had sailed', 'C', 'for days、动作持续到话语时间 → have been sailing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'How long ____ you ____ to join an Antarctic expedition?', 'did / want', 'have / wanted', 'are / wanting', 'have / been wanting', 'D', 'How long 问持续时间、强调愿望一直存在 → have been wanting。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'We ____ against the cold all day, and it is still snowing hard.', 'have been fighting', 'have fought', 'are fighting', 'fought', 'A', 'all day 表持续、动作仍在进行 → have been fighting。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'My nephew ____ stories of brave explorers since he was five.', 'collects', 'has been collecting', 'is collecting', 'collected', 'B', 'since he was five、动作从过去持续至今 → has been collecting。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'They ____ for a chance to be rescued ever since the ship sank.', 'wait', 'are waiting', 'have been waiting', 'waited', 'C', 'ever since + 过去事件、动作持续到现在 → have been waiting。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'For the whole morning the leader ____ the resolution to push on.', 'discusses', 'discussed', 'is discussing', 'has been discussing', 'D', 'For the whole morning 表一段时间、动作持续 → has been discussing。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'I ____ to phone the rescue base all afternoon, but no one answers.', 'have been trying', 'have tried', 'am trying', 'tried', 'A', 'all afternoon、反复尝试持续至今 → have been trying。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'He ____ how to be a navigator for over five years now.', 'learns', 'has been learning', 'is learning', 'learned', 'B', 'for over five years now、动作持续至今 → has been learning。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'The dog ____ at the ice since dawn, as if it senses danger.', 'barks', 'is barking', 'has been barking', 'barked', 'C', 'since dawn、动作从过去延续到现在 → has been barking。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'How long ____ the men ____ on Elephant Island so far?', 'did / live', 'are / living', 'have / lived', 'have / been living', 'D', 'How long ... so far、问持续时间 → have been living。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'We ____ this rocky shore for shelter for two hours without luck.', 'have been searching', 'have searched', 'are searching', 'searched', 'A', 'for two hours、动作持续(且未达成结果)→ have been searching。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'Frank ____ the others'' meals ever since he was made the cook.', 'cooks', 'has been cooking', 'is cooking', 'cooked', 'B', 'ever since + 过去时间、动作持续至今 → has been cooking。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'The storm ____ over the island for three days, with no sign of stopping.', 'rages', 'is raging', 'has been raging', 'raged', 'C', 'for three days、动作持续到现在并可能继续 → has been raging。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'Since the ship was crushed, the crew ____ in tents on the ice.', 'sleep', 'are sleeping', 'slept', 'have been sleeping', 'D', 'Since + 过去事件、动作持续至今 → have been sleeping。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'I ____ my courage up since the moment we left the safe harbour.', 'have been building', 'have built', 'am building', 'built', 'A', 'since the moment ...、动作从过去持续至今 → have been building。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'Steve ____ rugby since the age of eight, and now he plays for the team.', 'plays', 'has been playing', 'is playing', 'played', 'B', 'since the age of eight、动作持续至今 → has been playing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'The sailors ____ for South Georgia Island for many hours by now.', 'row', 'are rowing', 'have been rowing', 'rowed', 'C', 'for many hours by now、动作持续到现在 → have been rowing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.01'), 'How long ____ your team ____ to overcome this difficulty?', 'did / try', 'are / trying', 'have / tried', 'have / been trying', 'D', 'How long 问持续时间、强调持续努力 → have been trying。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'You look exhausted—____ you ____ out in the cold again?', 'have / been working', 'have / worked', 'are / working', 'did / work', 'A', '由''look exhausted''这一可见结果推断动作刚持续过 → have been working。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'It ____ all morning, so the whole camp is wet through.', 'has rained', 'has been raining', 'is raining', 'rained', 'B', 'all morning + 留下''camp is wet''的结果、强调持续 → has been raining。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'His hands are sore because he ____ at the frozen rope for ages.', 'pulls', 'is pulling', 'has been pulling', 'pulled', 'C', '''hands are sore''是动作持续留下的结果、for ages → has been pulling。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Why are your boots so muddy? ____ you ____ across the marsh?', 'Did / walk', 'Are / walking', 'Have / walked', 'Have / been walking', 'D', '由''boots so muddy''这一可见结果推断刚持续过的动作 → have been walking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Diane looks terrible today because she ____ much sleep all week.', 'hasn''t been getting', 'hasn''t got', 'isn''t getting', 'didn''t get', 'A', 'all week + ''looks terrible''的结果、强调持续 → hasn''t been getting。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The men''s eyes hurt; they ____ in the black smoke of the fire for hours.', 'sit', 'have been sitting', 'are sitting', 'sat', 'B', '''eyes hurt''是持续动作留下的结果、for hours → have been sitting。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Timmy looks tired and his hair is damp—he ____ rugby for two hours.', 'plays', 'is playing', 'has been playing', 'played', 'C', '''tired… hair is damp''的可见结果 + for two hours → has been playing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The kitchen smells of fat because the cook ____ seal meat all day.', 'fries', 'is frying', 'fried', 'has been frying', 'D', '''smells of fat''的结果 + all day、强调持续 → has been frying。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Your face is red and you''re out of breath—____ you ____ up the hill?', 'have / been running', 'have / run', 'are / running', 'did / run', 'A', '''face is red… out of breath''的可见结果 → have you been running。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The deck is soaked; waves ____ over the side for the past hour.', 'have washed', 'have been washing', 'are washing', 'washed', 'B', 'for the past hour + ''deck is soaked''的结果、强调反复持续 → have been washing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'He is covered in snow because he ____ the path clear all afternoon.', 'digs', 'is digging', 'has been digging', 'dug', 'C', '''covered in snow''的可见结果 + all afternoon → has been digging。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Why are your eyes so red? ____ you ____ over the bad news?', 'Did / cry', 'Are / crying', 'Have / cried', 'Have / been crying', 'D', '由''eyes so red''这一结果推断刚持续过的动作 → have you been crying。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The whole crew is shaking; they ____ in the freezing wind all night.', 'have been standing', 'have stood', 'are standing', 'stood', 'A', 'all night + ''shaking''的可见结果、强调持续 → have been standing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Her voice is hoarse because she ____ orders to the team for hours.', 'shouts', 'has been shouting', 'is shouting', 'shouted', 'B', '''voice is hoarse''的结果 + for hours → has been shouting。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The floor is full of ash; the fire ____ thick smoke all evening.', 'gives', 'is giving', 'has been giving', 'gave', 'C', '''full of ash''的结果 + all evening、强调持续 → has been giving。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'You smell of smoke—____ you ____ the seal fat for the lamps again?', 'Did / burn', 'Are / burning', 'Have / burned', 'Have / been burning', 'D', '由''smell of smoke''推断刚持续过的动作 → have you been burning。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The ropes are worn through because the men ____ them all week.', 'have been using', 'have used', 'are using', 'used', 'A', '''worn through''的结果 + all week、强调反复持续 → have been using。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'He looks proud and dirty—he ____ the rescue boat ready since morning.', 'gets', 'has been getting', 'is getting', 'got', 'B', '''proud and dirty''的可见结果 + since morning → has been getting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'The young sailor''s hands are blistered; he ____ ice for water for hours.', 'melts', 'is melting', 'has been melting', 'melted', 'C', '''hands are blistered''的结果 + for hours → has been melting。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.02'), 'Why is the tent so untidy? ____ the men ____ through the supplies?', 'Did / search', 'Are / searching', 'Have / searched', 'Have / been searching', 'D', '由''tent so untidy''这一结果推断刚持续过的动作 → have they been searching。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'I ____ the research paper at last; you can read it now.', 'have finished', 'have been finishing', 'am finishing', 'finish', 'A', '强调''已完成、有成果''→ have done(have finished),非进行体。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'We ____ as a team for hours, and we are still not giving up.', 'have worked', 'have been working', 'are working', 'worked', 'B', 'for hours + ''still not giving up''强调动作持续、未必完成 → have been working。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'Look—Shackleton ____ away from the island in the small boat right now.', 'has sailed', 'has been sailing', 'is sailing', 'sailed', 'C', 'right now、只描述此刻正在进行 → is sailing(现在进行时)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'The company ____ an advertising campaign, and it is now on every street.', 'has been launching', 'is launching', 'launches', 'has launched', 'D', '强调''已发起、现已上街''的完成结果 → has launched(have done)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'He ____ the navy three times so far, but he has never been accepted.', 'has tried', 'has been trying', 'is trying', 'tried', 'A', 'three times so far、强调''次数/已完成的尝试结果'' → has tried(have done)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'They ____ for a way off the ice all day, but none has been found yet.', 'have looked', 'have been looking', 'are looking', 'looked', 'B', 'all day + ''none found yet''强调持续未成 → have been looking。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'Quiet, please—the navigator ____ the map at this very moment.', 'has read', 'has been reading', 'is reading', 'read', 'C', 'at this very moment、只说此刻在做 → is reading(现在进行时)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'She ____ her diary, so the whole story of the voyage is now complete.', 'has been finishing', 'is finishing', 'finishes', 'has finished', 'D', '''story is now complete''强调完成结果 → has finished(have done)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'I ____ three penguins today, so we have enough food for the night.', 'have caught', 'have been catching', 'am catching', 'catch', 'A', '''enough food now''强调已完成的数量结果 → have caught(have done)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'The men ____ the same songs since dusk to keep their spirits up.', 'have sung', 'have been singing', 'are singing', 'sang', 'B', 'since dusk + 强调''一直在反复唱'' → have been singing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'Don''t disturb him—he ____ the broken motor in the corner now.', 'has fixed', 'has been fixing', 'is fixing', 'fixed', 'C', 'now + 只描述此刻动作 → is fixing(现在进行时)。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'We ____ the boat at last, and it is ready to set off.', 'have been repairing', 'are repairing', 'repair', 'have repaired', 'D', 'at last + ''ready now''强调完成结果 → have repaired(have done)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'He ____ his courage many times, and each test made him stronger.', 'has tested', 'has been testing', 'is testing', 'tested', 'A', 'many times + 强调已完成的若干次结果 → has tested(have done)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'They ____ to reach the whaling station since early morning, exhausted but hopeful.', 'have struggled', 'have been struggling', 'are struggling', 'struggled', 'B', 'since early morning + ''exhausted but hopeful''强调持续 → have been struggling。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'Watch out—the ice ____ under our feet at this moment!', 'has cracked', 'has been cracking', 'is cracking', 'cracked', 'C', 'at this moment、只说此刻正发生 → is cracking(现在进行时)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'The rescue ship ____, so everyone on the island is finally safe.', 'has been arriving', 'is arriving', 'arrives', 'has arrived', 'D', '''finally safe''强调已到达的完成结果 → has arrived(have done)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'I ____ that book about Shackleton; here it is if you want it.', 'have read', 'have been reading', 'am reading', 'read', 'A', '''here it is''强调读完、有结果 → have read(have done)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'The waves ____ against the rocks all night, and the noise never stops.', 'have crashed', 'have been crashing', 'are crashing', 'crashed', 'B', 'all night + ''noise never stops''强调反复持续 → have been crashing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'Be careful—the captain ____ to the crew over there just now.', 'has spoken', 'has been speaking', 'is speaking', 'spoke', 'C', 'over there just now、只描述此刻在做 → is speaking(现在进行时)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U4' AND code='e3u4.03'), 'We ____ our supplies carefully, so we know exactly what is left.', 'have been counting', 'are counting', 'count', 'have counted', 'D', '''know exactly what is left''强调完成的清点结果 → have counted(have done)。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Order to Abandon Ship', 'In 1915, the ship Endurance became trapped in the thick ice of the Antarctic. For months its crew waited, hoping the ice would melt and set them free. Instead, the pressure grew, until the wooden hull began to break apart. Captain Shackleton knew there was no more time to lose. He gave the order to abandon the ship before it sank, and the men dragged their boats, food, and tents out onto the frozen sea. They had been preparing for this terrible moment for weeks, yet leaving the warm ship still felt like losing a home. As the Endurance slipped beneath the ice, no one spoke. Shackleton, however, stayed calm. He told the crew that their goal was no longer the South Pole but simply getting everyone home alive. His steady voice gave the frightened men a strange new courage, and they began the long march across the ice with their leader at the front.', 'Adversity and Courage', 155, '[{"q":"Why did Shackleton order the men to leave the ship?","answer":"A","options":["Because the ice was crushing the hull and the ship would sink.","Because they had reached the South Pole.","Because the weather had become warm.","Because the men no longer wanted to explore."],"explanation":"由 ''the pressure grew… break apart… before it sank'' 概括转述。"},{"q":"How did the men feel about leaving the Endurance?","answer":"B","options":["Excited and relieved.","Although expected, parting with the ship felt like leaving their home.","Bored and uninterested.","Eager to reach the South Pole."],"explanation":"原文 ''leaving the warm ship still felt like losing a home'' 的转述。"},{"q":"What new goal did Shackleton give the crew?","answer":"A","options":["To bring everyone home alive.","To find more ice.","To build a new ship at once.","To continue south as planned."],"explanation":"由 ''getting everyone home alive'' 概括,非照抄连续子串。"}]'::jsonb, '[{"word":"abandon","cn":"弃(船);放弃"},{"word":"crew","cn":"全体船员"},{"word":"hull","cn":"船身;船体"}]'::jsonb, 2, 'elective3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Four Months on Elephant Island', 'After their leader sailed away to look for help, the remaining men were left on a cold and rocky shore called Elephant Island. The place had no trees and no fresh water. To survive, they melted sea ice for drinking water and burned animal fat for fire, since there was no wood or oil. Food was a constant worry, for they could find no fruit or vegetables, only the meat of the sea creatures they managed to catch. The cook did his best to make the meals less boring, but it was hard. What truly kept the group alive, however, was not food but spirit. They celebrated birthdays and festivals, sang songs in the evenings, and shared every small piece of good news. Their discipline and team spirit helped them face their fears in a positive way. For four long months the twenty-two men waited in the freezing cold, never quite losing hope that their leader would return for them.', 'Adversity and Courage', 160, '[{"q":"How did the men get water on the island?","answer":"B","options":["They melted sea ice to drink.","They carried it from the ship.","It rained every day.","They found a fresh spring."],"explanation":"原文 ''melted sea ice for drinking water'' 的转述。"},{"q":"According to the passage, what kept the group alive most of all?","answer":"C","options":["A large store of fruit.","The help of passing ships.","Their team spirit and discipline.","The warm island weather."],"explanation":"由 ''kept the group alive… was not food but spirit… discipline and team spirit'' 概括。"},{"q":"How long did the men wait on Elephant Island?","answer":"D","options":["A few days.","About two weeks.","Almost a year.","Four months."],"explanation":"原文 ''For four long months… waited'' 的转述。"}]'::jsonb, '[{"word":"survive","cn":"幸存;活下来"},{"word":"discipline","cn":"纪律;自律"},{"word":"spirit","cn":"精神;斗志"}]'::jsonb, 2, 'elective3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Crossing the Mountains of South Georgia', 'Shackleton''s small boat finally reached South Georgia Island, but the journey was not over. The whaling station, where they could ask for help, lay on the far side of the island, beyond a wall of unmapped mountains and glaciers. No one had ever crossed them before. With almost no climbing gear and very little food, Shackleton and two companions set off on foot. For thirty-six hours they climbed up icy slopes and slid down dangerous snow fields, not daring to stop and rest in case they froze. At one point, trapped on a steep ridge as night fell, they chose to slide together down an unknown slope into the darkness rather than wait and die of cold. By luck and courage, they survived. When the three exhausted men finally walked into the station, the workers hardly recognised them, for they looked like wild old men. Yet their perseverance had saved every member of the crew left behind.', 'Adversity and Courage', 157, '[{"q":"Why did Shackleton have to cross the mountains?","answer":"A","options":["The whaling station with help was on the other side of the island.","He wanted to enjoy the view.","He was looking for a new ship.","He had lost his way completely."],"explanation":"由 ''whaling station, where they could ask for help, lay on the far side'' 概括。"},{"q":"What did the three men do when trapped on the ridge at night?","answer":"B","options":["They waited quietly until morning.","They slid down an unknown slope rather than freeze.","They built a warm shelter.","They turned back the way they came."],"explanation":"原文 ''chose to slide together down an unknown slope… rather than wait and die of cold'' 的转述。"},{"q":"Why did the station workers hardly recognise the men?","answer":"C","options":["The men were wearing fine new clothes.","It was too dark to see anyone.","Their ordeal had left them looking wild and aged.","The men spoke a different language."],"explanation":"由 ''looked like wild old men'' 概括。"}]'::jsonb, '[{"word":"glacier","cn":"冰川"},{"word":"ridge","cn":"山脊"},{"word":"perseverance","cn":"毅力;不屈不挠"}]'::jsonb, 2, 'elective3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Trapped Under a Rock', 'Adversity does not only strike at sea. In 2003, a young American climber named Aron Ralston went hiking alone in a narrow desert canyon. As he climbed down, a huge rock shifted and trapped his right arm against the canyon wall. He was completely alone, and no one knew exactly where he was. For more than five days he stood there, slowly running out of water and food. He had been calling for help for hours, but no answer ever came. At last, Ralston understood that no rescue was coming. With astonishing courage, he made the hardest decision of his life: he cut off his own trapped arm to free himself. Then, weak and bleeding, he climbed out of the canyon and walked until he met other hikers who could save him. His story spread around the world. People were amazed not only by what he did to survive, but by the calm and determined spirit that carried him through.', 'Adversity and Courage', 160, '[{"q":"What happened to Aron Ralston in the canyon?","answer":"D","options":["His arm was trapped by a heavy rock.","He got lost in a sandstorm.","He met a wild animal.","He fell into a river."],"explanation":"由 ''a huge rock shifted and trapped his right arm'' 概括转述。"},{"q":"Why did no one come to help him?","answer":"A","options":["He was alone and nobody knew where he was.","He had a radio but it was broken.","His friends ignored his calls.","Rescue teams refused to search."],"explanation":"原文 ''completely alone, and no one knew exactly where he was'' 的转述。"},{"q":"What amazed people most about Ralston''s story?","answer":"B","options":["The beauty of the canyon.","His calm, determined spirit in surviving.","The number of days he slept.","The price of his climbing gear."],"explanation":"由 ''the calm and determined spirit that carried him through'' 概括。"}]'::jsonb, '[{"word":"canyon","cn":"峡谷"},{"word":"trapped","cn":"被困住的"},{"word":"determined","cn":"坚定的;有决心的"}]'::jsonb, 2, 'elective3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Climbing in the Dark', 'When Erik Weihenmayer was a teenager, he lost his sight completely. Many people thought his active life was over, but Erik refused to give up the things he loved. Step by step, he learned to live in a world he could no longer see. He began rock climbing, feeling the shape of every hold with his fingers and listening to the voices of friends who guided him from above. Year after year he climbed harder and higher mountains, training his body and mind to trust touch and sound instead of sight. In 2001 he reached the top of the world''s highest mountain, becoming the first blind person ever to do so. Reaching the summit, he said, was not really about proving anything to others. It was about showing that adversity need not decide what a person can become. Today Erik travels the world, telling young people that the biggest mountains we face are often the ones inside our own minds.', 'Adversity and Courage', 160, '[{"q":"What difficulty did Erik face as a teenager?","answer":"C","options":["He broke both of his legs.","He could no longer hear.","He became completely blind.","He had to move to a new country."],"explanation":"原文 ''lost his sight completely'' 的转述。"},{"q":"How did Erik manage to climb without seeing?","answer":"D","options":["He used a special camera.","He climbed only very small hills.","He waited until his sight returned.","He relied on touch and on friends'' voices."],"explanation":"由 ''feeling the shape of every hold… listening to the voices of friends'' 概括。"},{"q":"What message does Erik share with young people?","answer":"A","options":["The hardest mountains are often inside our minds.","Only strong bodies matter.","Blindness makes climbing impossible.","Everyone should climb the highest peak."],"explanation":"由 ''the biggest mountains we face are often the ones inside our own minds'' 概括。"}]'::jsonb, '[{"word":"sight","cn":"视力;视觉"},{"word":"summit","cn":"顶峰;山顶"},{"word":"hold","cn":"(攀岩的)抓握点"}]'::jsonb, 2, 'elective3', 'U4');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Why Some People Never Give Up', 'Why do some people keep going through terrible hardship, while others give up? Scientists who study courage have found that it is not simply a matter of being born brave. Much of it depends on attitude and habit. People who keep going tend to focus on the next small step rather than on the huge problem as a whole. Instead of asking, ''How will I survive a whole month?'', they ask, ''How do I get through the next hour?'' This way of thinking turns a frightening challenge into something they can actually handle. Such people also tend to believe that their own actions make a difference, so they keep trying instead of waiting helplessly. Just as importantly, they look after one another. In groups facing danger, those who support their companions usually do better than those who think only of themselves. Courage, the researchers say, is less a gift and more a skill—one that anyone can slowly build through practice and hope.', 'Adversity and Courage', 162, '[{"q":"According to scientists, what does courage mostly depend on?","answer":"B","options":["Being born brave.","A person''s attitude and habits.","Great physical strength alone.","Pure luck."],"explanation":"由 ''not simply… born brave… depends on attitude and habit'' 概括。"},{"q":"How do people who never give up tend to think?","answer":"C","options":["They imagine the worst possible ending.","They wait for others to act first.","They concentrate on the very next step rather than the entire problem.","They ignore the danger completely."],"explanation":"由 ''focus on the next small step rather than on the huge problem'' 概括。"},{"q":"What helps groups do better in danger?","answer":"D","options":["Thinking only of oneself.","Travelling separately.","Avoiding all risk.","Supporting one another."],"explanation":"由 ''those who support their companions usually do better'' 概括。"}]'::jsonb, '[{"word":"attitude","cn":"态度"},{"word":"handle","cn":"应对;处理"},{"word":"companion","cn":"同伴"}]'::jsonb, 2, 'elective3', 'U4');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U4', 'The Boy Who Hid Aboard', 'Perce Blackborow was a young man who longed for (1)____. When he heard that a great expedition to the Antarctic needed brave men, he was so (2)____ that he asked to join at once. Sadly, his application was turned (3)____, because the leaders thought he was too young and not (4)____ enough. But Perce would not give up. With a friend''s help, he secretly got (5)____ the ship and hid in a dark (6)____ until they were far out at sea. When he was finally (7)____, the captain was angry, yet he could not help admiring the boy''s courage. Instead of sending him away, he (8)____ Perce the job of cooking for the (9)____. From that day on, Perce worked hard and never complained, proving that his (10)____ to join had been right all along.', 135, 2, '[{"q":"1","answer":"A","options":["adventure","furniture","wage","stove"],"explanation":"longed for adventure 渴望冒险。"},{"q":"2","answer":"B","options":["selfish","enthusiastic","cruel","damp"],"explanation":"so enthusiastic 如此热情。"},{"q":"3","answer":"C","options":["up","off","down","in"],"explanation":"turned down 被拒绝。"},{"q":"4","answer":"D","options":["miserable","loyal","rough","qualified"],"explanation":"not qualified enough 不够格。"},{"q":"5","answer":"A","options":["aboard","across","above","along"],"explanation":"got aboard the ship 登上船。"},{"q":"6","answer":"B","options":["motor","cupboard","navy","voyage"],"explanation":"hid in a cupboard 藏在橱柜里。"},{"q":"7","answer":"C","options":["abandoned","advertised","discovered","assigned"],"explanation":"was finally discovered 终被发现。"},{"q":"8","answer":"D","options":["sold","lost","left","assigned"],"explanation":"assigned Perce the job 把工作分派给他。"},{"q":"9","answer":"A","options":["crew","guidance","envy","resolve"],"explanation":"cooking for the crew 给船员做饭。"},{"q":"10","answer":"B","options":["weather","resolve","price","noise"],"explanation":"his resolve to join 他加入的决心。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U4', 'The Cook on the Ice', 'Life on the ice was hard, and feeding the men was the (1)____ of the young cook. There were no shops and no fresh food, only the (2)____ of the sea animals the crew managed to catch. Day after day he (3)____ the same meat in different ways, trying to make it taste better. To make fire, he burned animal fat, which gave (4)____ thick, oily smoke that hurt everyone''s eyes. The work was (5)____ and dirty, but he never lost his good (6)____. He knew that a warm meal could lift the (7)____ of the whole group on a freezing night. Whenever someone felt low, the cook would offer a hot drink and a kind (8)____. His care helped the men stay (9)____ through the long, dark months. Years later, he remembered this difficult time as one of the proudest (10)____ of his whole life.', 146, 2, '[{"q":"1","answer":"C","options":["vigour","motive","duty","navy"],"explanation":"the duty of the cook 厨子的职责。"},{"q":"2","answer":"D","options":["wages","stoves","ridges","meat"],"explanation":"the meat of the sea animals 海洋动物的肉。"},{"q":"3","answer":"A","options":["cooked","abandoned","advertised","assigned"],"explanation":"cooked the same meat 烹饪同样的肉。"},{"q":"4","answer":"B","options":["up","off","in","back"],"explanation":"gave off smoke 散发出烟。"},{"q":"5","answer":"C","options":["cosy","decent","rough","loyal"],"explanation":"rough and dirty 又苦又脏。"},{"q":"6","answer":"D","options":["price","wage","stove","temper"],"explanation":"good temper 好脾气。"},{"q":"7","answer":"A","options":["spirits","smoke","ice","boats"],"explanation":"lift the spirits 提振士气。"},{"q":"8","answer":"B","options":["machine","word","engine","garden"],"explanation":"a kind word 一句善言。"},{"q":"9","answer":"C","options":["selfish","cruel","hopeful","miserable"],"explanation":"stay hopeful 保持希望。"},{"q":"10","answer":"D","options":["mistakes","prices","noises","episodes"],"explanation":"the proudest episodes 最自豪的经历。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U4', 'A Few Words on Courage', 'Many people think that courage means feeling no (1)____ at all. In fact, brave people are often afraid, but they act in (2)____ of their fear. The first (3)____ of courage is simply to take one small step forward. When a problem feels too (4)____, do not look at the whole mountain; look only at the next stone under your foot. Another secret is to (5)____ on, even when progress is slow. Those who keep going through (6)____ usually win in the end. It also (7)____ to share your fears with someone you trust, because a problem (8)____ is a problem made smaller. Finally, remember to help the people around you. In hard times, those who think only of (9)____ rarely do well, while those who support others find new (10)____ they did not know they had.', 137, 2, '[{"q":"1","answer":"A","options":["fear","wage","stove","voyage"],"explanation":"feeling no fear 毫无恐惧。"},{"q":"2","answer":"B","options":["place","spite","honour","search"],"explanation":"in spite of their fear 不顾恐惧。"},{"q":"3","answer":"C","options":["price","noise","secret","weather"],"explanation":"the first secret 第一个秘诀。"},{"q":"4","answer":"D","options":["cosy","loyal","damp","huge"],"explanation":"too huge 太巨大。"},{"q":"5","answer":"A","options":["press","give","sell","lose"],"explanation":"press on 坚持前进。"},{"q":"6","answer":"B","options":["recreation","adversity","envy","guidance"],"explanation":"through adversity 历经逆境。"},{"q":"7","answer":"C","options":["sells","breaks","helps","loses"],"explanation":"it helps to ... 有帮助。"},{"q":"8","answer":"D","options":["sold","lost","broken","shared"],"explanation":"a problem shared 分担的问题。"},{"q":"9","answer":"A","options":["themselves","others","everyone","nobody"],"explanation":"think only of themselves 只想自己。"},{"q":"10","answer":"B","options":["machines","strength","prices","gardens"],"explanation":"new strength 新的力量。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U4', 'The Runner Who Would Not Quit', 'At the start of the long race, no one paid much (1)____ to John, a quiet runner near the back. Halfway through, he fell badly and hurt his (2)____. The pain was sharp, and many told him to (3)____ up and rest. But John shook his head and slowly got back on his (4)____. He had been (5)____ for this race for a whole year, and he would not waste all that effort. Step by painful step, he kept (6)____ forward, far behind the others. The crowd grew quiet, then began to (7)____ his name. When at last he crossed the finish line, he was the (8)____ runner of all, yet he received the loudest (9)____ of the day. John later said that the medal did not matter; what mattered was that he had not let his (10)____ defeat him.', 140, 2, '[{"q":"1","answer":"C","options":["stove","wage","attention","navy"],"explanation":"pay attention to 注意。"},{"q":"2","answer":"D","options":["voyage","crew","motor","knee"],"explanation":"hurt his knee 伤了膝盖。"},{"q":"3","answer":"A","options":["give","turn","press","set"],"explanation":"give up 放弃。"},{"q":"4","answer":"B","options":["price","feet","noise","weather"],"explanation":"got back on his feet 重新站起。"},{"q":"5","answer":"C","options":["abandoning","selling","training","losing"],"explanation":"had been training 一直在训练。"},{"q":"6","answer":"D","options":["selling","losing","hiding","moving"],"explanation":"kept moving forward 继续前进。"},{"q":"7","answer":"A","options":["chant","sell","break","lose"],"explanation":"chant his name 高呼他的名字。"},{"q":"8","answer":"B","options":["fastest","slowest","richest","youngest"],"explanation":"the slowest runner 最慢的选手。"},{"q":"9","answer":"C","options":["machine","engine","cheer","garden"],"explanation":"the loudest cheer 最响的欢呼。"},{"q":"10","answer":"D","options":["wage","stove","cupboard","pain"],"explanation":"let his pain defeat him 让疼痛打败他。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U4', 'Lost in the Desert', 'Maria had been hiking in the desert for hours when she realised she was (1)____. The sun was (2)____ behind the hills, and her water was almost gone. Fear rose in her chest, but she forced herself to stay (3)____. Panic, she knew, would only make things (4)____. First, she stopped and (5)____ about her situation carefully. Then she remembered a piece of (6)____ her father had once given her: in trouble, stay where you are and make yourself easy to (7)____. So she built a small fire that gave (8)____ a tall line of smoke. All night she fed the (9)____, keeping it burning in the cold wind. At dawn, a rescue plane saw the smoke and circled overhead. Maria waved with all her (10)____, and within an hour she was safe. Her calm thinking had saved her life.', 140, 2, '[{"q":"1","answer":"A","options":["lost","loyal","cosy","damp"],"explanation":"she was lost 她迷路了。"},{"q":"2","answer":"B","options":["barking","sinking","abandoning","advertising"],"explanation":"the sun was sinking 太阳正下沉。"},{"q":"3","answer":"C","options":["angry","afraid","calm","selfish"],"explanation":"stay calm 保持冷静。"},{"q":"4","answer":"D","options":["better","easier","safer","worse"],"explanation":"make things worse 使情况更糟。"},{"q":"5","answer":"A","options":["thought","sold","lost","hid"],"explanation":"thought about 思考。"},{"q":"6","answer":"B","options":["weather","advice","noise","price"],"explanation":"a piece of advice 一条建议。"},{"q":"7","answer":"C","options":["sell","lose","find","hide"],"explanation":"easy to find 容易被找到。"},{"q":"8","answer":"D","options":["up","in","back","off"],"explanation":"gave off smoke 散发烟雾。"},{"q":"9","answer":"A","options":["fire","machine","engine","garden"],"explanation":"fed the fire 给火添柴。"},{"q":"10","answer":"B","options":["price","might","noise","weather"],"explanation":"with all her might 用尽全力。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U4', 'A Letter to a Friend', 'Dear Tom, I heard that you have been (1)____ a hard time at school lately, and I want you to know that you are not (2)____. Everyone meets (3)____ sooner or later; what matters is how we face it. Please do not (4)____ up on the things you love. When I failed my first exams, I felt (5)____ too, but my sister gave me good (6)____: take one small step each day. Little by (7)____, things got easier. Try to find one person you can (8)____, and share how you feel; a worry shared is much lighter. Remember that this difficult time is only an (9)____ in your long life, not the whole story. I truly believe you have the (10)____ to get through it. Stay strong, and write back soon. Your friend, Anna.', 134, 2, '[{"q":"1","answer":"C","options":["selling","abandoning","having","advertising"],"explanation":"have been having a hard time 一直过得艰难。"},{"q":"2","answer":"D","options":["loyal","cruel","damp","alone"],"explanation":"you are not alone 你并不孤单。"},{"q":"3","answer":"A","options":["difficulties","wages","stoves","voyages"],"explanation":"meets difficulties 遇到困难。"},{"q":"4","answer":"B","options":["turn","give","press","set"],"explanation":"give up 放弃。"},{"q":"5","answer":"C","options":["cosy","loyal","miserable","decent"],"explanation":"felt miserable 感到痛苦。"},{"q":"6","answer":"D","options":["weather","noise","price","advice"],"explanation":"good advice 好建议。"},{"q":"7","answer":"A","options":["little","lot","much","many"],"explanation":"little by little 一点一点。"},{"q":"8","answer":"B","options":["sell","trust","lose","hide"],"explanation":"someone you can trust 你能信任的人。"},{"q":"9","answer":"C","options":["machine","engine","episode","garden"],"explanation":"an episode 一段经历。"},{"q":"10","answer":"D","options":["price","noise","weather","courage"],"explanation":"the courage to get through 度过难关的勇气。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·对话 Choosing the Rescue Team', '选择性必修三 U4 · dialogue', 3, 'A: We must choose two more sailors for the rescue boat. Who do you suggest?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·短文 What Courage Really Means', '选择性必修三 U4 · passage', 2, 'Many people believe that brave heroes never feel afraid.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·对话 Interview with a Climber', '选择性必修三 U4 · dialogue', 3, 'A: You climbed the mountain after losing your sight. Wasn''t that frightening?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·短文 The Power of One Small Step', '选择性必修三 U4 · passage', 2, 'When a problem feels too big, it can stop us before we even begin.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·对话 Getting Ready for the Expedition', '选择性必修三 U4 · dialogue', 3, 'A: The expedition leaves next month. Have you been preparing for it?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U4 听力·短文 A Word for Hard Times', '选择性必修三 U4 · passage', 2, 'If you are going through a hard time, please remember that you are not alone.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Write a letter encouraging a friend who is facing adversity(给身处逆境的朋友写一封鼓励信)', 'A Letter of Encouragement', '假设你叫李华,你的好友 Tom 因一次考试失利而情绪低落,甚至想放弃。请用英语给他写一封约100词的信,内容包括:① 表达理解和安慰;② 用一个克服逆境的小故事(如沙克尔顿带领船员绝境求生)鼓励他;③ 给出一两条具体建议并表达信心。注意书信格式,语句围绕中心、连贯地道。', 'Suppose you are Li Hua. Your good friend Tom feels low after failing an important exam and even wants to give up. Write a letter (about 100 words) to encourage him, including: 1) understanding and comfort; 2) a short story of overcoming adversity (e.g. how Shackleton led his crew to survive) to encourage him; 3) one or two pieces of practical advice and your confidence in him.', '["表达理解与安慰(I''m sorry to hear … / Please don''t lose heart)","用克服逆境的故事鼓励(Think of Shackleton, who …)","给出具体建议(Take one small step each day / Talk to someone you trust)","表达信心、书信格式完整(I''m sure you''ll get through this. Yours, Li Hua)"]'::jsonb, 70, 100, 'Dear Tom,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective3', 'U4', '{"title":"现在完成进行时 have/has been doing 速查","intro":"现在完成进行时强调动作从过去某时一直持续(或反复)到现在,常带时间标志,或留下明显结果。结构:have/has been + 现在分词(doing)。判断口诀:有 for/since/all day/how long 又强调''一直在做''→ 用 have been doing。","table":{"headers":["用法","标志 / 例句"],"rows":[["持续到现在的动作","for/since/all day/how long:I have been training for months."],["反复进行的动作","强调一次次重复:She has been calling me all morning."],["刚结束留下结果","由可见结果反推:You''re wet—have you been running?"],["对照 have done","强调结果/完成用 have done:I have finished it.(完成)"],["对照 am doing","只说此刻在做用现在进行时:He is sailing now.(此刻)"]]},"specialRules":[{"rule":"have/has been doing 强调''动作持续/反复到现在'',未必已完成","mark":"I have been reading this book.(还没读完)"},{"rule":"have done 强调''已完成、有结果''","mark":"I have read this book.(读完了)"},{"rule":"状态动词(know/like/be 等)一般不用进行体","mark":"I have known him for years. √ / have been knowing ×"},{"rule":"由可见结果(累了/湿了/脏了)反推刚刚一直在做","mark":"Your eyes are red—have you been crying?"}],"why":["have been doing 用 been + doing 把''完成''(been)和''进行''(doing)合在一起,所以既看得见动作从过去拉到现在,又强调它一直在持续或反复;一旦只关心结果或只关心此刻,就分别换成 have done 或 am doing。"],"gaokaoPoints":["for/since/all day/how long + 强调持续 → have/has been doing,语法填空与短文改错高频。","have been doing(持续/未必完成) vs have done(已完成/结果) vs am doing(此刻)三者对照辨析是核心考点。","状态动词、瞬间动词一般不进入完成进行时,需识别陷阱。"],"examVsReal":[{"exam":"I have been waiting for an hour.(考试强调持续)","real":"I''ve been waiting an hour.","note":"口语常缩写 I''ve、省略 for;意义一致"},{"exam":"It has been raining all day.(考试规范)","real":"It''s been raining all day.","note":"口语用 it''s been;现在完成进行时在日常英语中很常用,并不书面化"}]}'::jsonb);
